import json
from pathlib import Path
P=Path(__file__).resolve().parent
rs=json.loads((P/'remaining-initial.json').read_text());done={x['Form_ID'] for f in P.glob('pass*-saved-assignments.json') for x in json.loads(f.read_text())}
groups=[{'parent': '13992', 'gloss': ['turmeric'], 'forms': ['halaḍi', 'halḍi', 'hal̃ḍi', 'haḷāḍi', 'hāḷḍ', 'haḷḍ', 'halḍ', 'hāṛḍ', 'hād', 'haliḍ', 'hūḷīḍ', 'haḷath', 'aleḍi'], 'citation': 'CDIAL[13992,1 and addenda]', 'evidence': 'Turner’s first haridrā branch includes Prakrit haladdā/haliddā, Hindi haladdī/haldī, Gujarati haḷad/haḷdar and Marathi haḷad. The retained l/ḷ plus retroflex-stop survey forms and contracted Gujari hād fit that turmeric series; vowel and aspiration variation is preserved. The hāridra dyed-with-turmeric subsection is not selected.'}, {'parent': '13992', 'gloss': ['turmeric'], 'forms': ['elḍɔ', 'elḍo', 'elḍa'], 'languages': ['Noiri', 'DungraBhili'], 'citation': 'CDIAL[13992,1]', 'evidence': 'The Noiri/Dungra elḍ- turmeric noun compares with Gujarati haḷad and Hindi haladdī in Turner’s haridrā branch. This placement allows initial h loss, contraction and the recorded initial e vowel; it is a regional lexical comparison, with the o/a endings retained and no claim to a newly established sound law.'}, {'parent': '13992', 'gloss': ['turmeric'], 'forms': ['hālīź', 'hālīźū', 'halīźū', 'hālīẓ', 'hælīṣ'], 'languages': ['Mai', 'Chil', 'Gowro', 'bhatr', 'Tor'], 'citation': 'CDIAL[13992,1];zoller2005[p. 410]', 'evidence': 'Zoller explicitly derives Indus Kohistani həlīẓ/həlīṣ turmeric from haridrā (CDIAL 13992); Turner also gives Shina haliẓi. The survey hāliź/hæliṣ forms preserve this diagnostic northwestern outcome, including the source’s palatal/retroflex notation and final vowel where present. This is not the unrelated halīṣā plough-pole entry printed immediately above in Zoller.'}, {'parent': 'f_3t4wa5zxpb2bm', 'kind': 'borrowed', 'gloss': ['garlic'], 'forms': ['hūgi', 'hūgī'], 'languages': ['Mai', 'Chil', 'Gowro', 'bhatr'], 'citation': 'zoller2005[p. 414];hallberg1992pashto[Appendix B, p. 104, item 77]', 'evidence': 'Zoller explicitly compares Indus Kohistani huigi/hugi garlic to Pashto hūga. These closely matching survey forms are assigned as loans using the existing Pashto ūgā donor attestation; that node represents the Pashto lexical family, not a claim that the exact Charsadda vowel/initial realization was the local donor. Transmission through a neighbouring Kohistani variety remains possible.'}, {'parent': '2723', 'gloss': ['onion'], 'forms': ['kāṇḍo', 'kāṇḍu', 'kānḍu', 'kandū', 'kānto', 'kāntā'], 'languages': ['Vasavi', 'Noiri', 'PauriBareli', 'PalyaBareli', 'Bhilali'], 'citation': 'CDIAL[2723]', 'evidence': 'Turner gives Gujarati kā̃dɔ, Marathi kā̃dā and Konkani kā̃ndo onion under kanda bulbous root. These western survey kāṇḍ-/kand- and devoiced kānt- forms fit that bulb/onion family; source nasal/retroflex spellings are preserved. They are separated from the granthi knot-derived gaṇḍ-/gaṇṭh- onion words.'}, {'parent': '4354', 'gloss': ['onion'], 'forms': ['gaṇḍo', 'ganṭa', 'ganda', 'ganṭʰā', 'ganṭiõ', 'gaṭʰā', 'ganṭʰiā', 'gaṇṭʰī'], 'citation': 'CDIAL[4354 and addenda]', 'evidence': 'Turner’s granthi knot family explicitly includes Sindhi gaṇḍhi onion bulb and Lahnda gaḍḍh onion/gaṇḍhā bulb, beside Hindi gā̃ṭhī/gā̃ṭhā. The Gujari/Dogri and Haryanvi/Buksa onion responses match this documented bulb sense; nasal versus written nasal-stop and aspiration realizations remain as transcribed. The unrelated kanda onion series is kept separate.'}]
a=[]
for i,g in enumerate(groups):
 for r in rs:
  if r['ID'] not in done and r['Gloss'] in g['gloss'] and r['Form'] in g['forms'] and ('languages' not in g or r['Language_ID'] in g['languages']):
   a.append(dict(record=r,parent=g['parent'],kind=g.get('kind','reflex'),citation=g['citation'],evidence=g['evidence'],family=i))
assert len(a)==len({x['record']['ID'] for x in a})
h=[]
(P/'pass043-decisions.json').write_text(json.dumps(dict(accepted=a,held=h),ensure_ascii=False,indent=1)+'\n')
(P/'pass043-rules.json').write_text(json.dumps(groups,ensure_ascii=False,indent=1)+'\n')
print(len(a),'accepted',len(h),'held',[(g['parent'],sum(x['family']==i for x in a)) for i,g in enumerate(groups)])
